package com.bank.expr;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

// All three DFS traversals, recursive and iterative.
public class TraversalService {

    // ---------- Recursive ----------
    public List<String> preorderRecursive(ExprNode root) {
        List<String> out = new ArrayList<>();
        preorder(root, out);
        return out;
    }
    private void preorder(ExprNode node, List<String> out) {
        if (node == null) return;
        out.add(node.getToken());         // node first
        preorder(node.getLeft(), out);
        preorder(node.getRight(), out);
    }

    public List<String> inorderRecursive(ExprNode root) {
        List<String> out = new ArrayList<>();
        inorder(root, out);
        return out;
    }
    private void inorder(ExprNode node, List<String> out) {
        if (node == null) return;
        inorder(node.getLeft(), out);
        out.add(node.getToken());         // node between
        inorder(node.getRight(), out);
    }

    public List<String> postorderRecursive(ExprNode root) {
        List<String> out = new ArrayList<>();
        postorder(root, out);
        return out;
    }
    private void postorder(ExprNode node, List<String> out) {
        if (node == null) return;
        postorder(node.getLeft(), out);
        postorder(node.getRight(), out);
        out.add(node.getToken());         // node last
    }

    // ---------- Iterative ----------
    public List<String> preorderIterative(ExprNode root) {
        List<String> out = new ArrayList<>();
        if (root == null) return out;
        Deque<ExprNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            ExprNode n = stack.pop();
            out.add(n.getToken());
            if (n.getRight() != null) stack.push(n.getRight()); // right first
            if (n.getLeft() != null) stack.push(n.getLeft());   // left on top
        }
        return out;
    }

    public List<String> inorderIterative(ExprNode root) {
        List<String> out = new ArrayList<>();
        Deque<ExprNode> stack = new ArrayDeque<>();
        ExprNode curr = root;
        while (curr != null || !stack.isEmpty()) {
            while (curr != null) {           // go as far left as possible
                stack.push(curr);
                curr = curr.getLeft();
            }
            curr = stack.pop();              // leftmost unvisited
            out.add(curr.getToken());
            curr = curr.getRight();          // then explore right
        }
        return out;
    }

    public List<String> postorderIterative(ExprNode root) {
        // Modified preorder (node-right-left), then reverse.
        List<String> out = new ArrayList<>();
        if (root == null) return out;
        Deque<ExprNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            ExprNode n = stack.pop();
            out.add(n.getToken());
            if (n.getLeft() != null) stack.push(n.getLeft());
            if (n.getRight() != null) stack.push(n.getRight());
        }
        Collections.reverse(out);            // → left-right-node
        return out;
    }
}
