package com.bank.expr;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class TraversalDemo {

    private static final Logger log = Logger.getLogger(TraversalDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Fee Expression Tree Traversals");

        // Expression: (base + fee) * tax
        //            *
        //          /   \
        //         +     tax
        //        / \
        //     base  fee
        ExprNode mul = new ExprNode("*");
        ExprNode add = new ExprNode("+");
        mul.setLeft(add);
        mul.setRight(new ExprNode("tax"));
        add.setLeft(new ExprNode("base"));
        add.setRight(new ExprNode("fee"));

        TraversalService svc = new TraversalService();
        log.info("Preorder  (recursive): " + svc.preorderRecursive(mul));
        log.info("Preorder  (iterative): " + svc.preorderIterative(mul));
        log.info("Inorder   (recursive): " + svc.inorderRecursive(mul));
        log.info("Inorder   (iterative): " + svc.inorderIterative(mul));
        log.info("Postorder (recursive): " + svc.postorderRecursive(mul));
        log.info("Postorder (iterative): " + svc.postorderIterative(mul));
    }
}
